/* Study display and navigation. Protocol resolution, metrics and execution are Python-owned. */
function studyEscape(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function studyAccept(opened,generation,key,data){return opened&&String(generation)===key&&data.key===key;}
function createStudiesWorkspace({root,getResult,pause,replay}){
 const w=root.querySelector('.st-workspace');if(!w)return {open(){},close(){},isOpen:()=>false};
 const q=s=>w.querySelector(s),esc=studyEscape,num=(v,d=2)=>Number.isFinite(v)?v.toLocaleString('en-GB',{maximumFractionDigits:d,minimumFractionDigits:d}):'—';
 let opened=false,generation=0,edition=null,editions=[],data=null,spec=null,timer=null,returnFocus=null,inertBefore=[],panel=null,previewReady=false,pinnedReport=null,protocolCatalogue=[],newParent=null,newSpec=null;
 function status(message){q('.st-status').textContent=message||'';}
 function request(operation,extra={},key=String(generation)){const r=getResult();return {token:r.study_token,run_id:r.run_id,key,operation,...extra};}
 async function post(body){const res=await fetch('/dispatch/studies',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const value=await res.json();if(!res.ok)throw Error(typeof value.detail==='string'?value.detail:'Study request failed');if(value.error)throw Error(value.error);return value;}
 function close(){if(!opened)return;opened=false;generation++;clearTimeout(timer);w.hidden=true;root.removeAttribute('data-studies-open');for(const [n,inert] of inertBefore)if(n.isConnected)n.inert=inert;returnFocus?.isConnected?returnFocus.focus({preventScroll:true}):root.querySelector('[data-do=menu]')?.focus({preventScroll:true});}
 async function open(id=null,reportId=null){if(getResult().offline_mode)return;if(!opened){returnFocus=document.activeElement;inertBefore=[...root.children].filter(n=>n!==w).map(n=>[n,n.inert]);}pause();opened=true;w.inert=false;w.hidden=false;root.dataset.studiesOpen='true';for(const [n] of inertBefore)n.inert=true;q('[data-st=back]').focus({preventScroll:true});await list(id,reportId);}
 async function list(id=null,reportId=null){const key=String(++generation);clearTimeout(timer);status('Loading study editions…');try{const value=await post(request('list',{},key));if(!studyAccept(opened,generation,key,value))return;editions=value.editions;spec=value.protocol;protocolCatalogue=value.protocols||[spec];renderIndex();const target=id||editions.find(e=>e.status==='complete')?.edition_id||editions[0]?.edition_id;if(target)await view(target,reportId);else{data=null;edition=null;q('.st-article').hidden=false;q('.st-panel').hidden=true;q('.st-article').innerHTML=`<h1>${esc(spec.title)}</h1><p class="st-question">${esc(spec.question)}</p><p>${esc(spec.rationale)}</p><p>No study editions have been executed yet. The protocol is authored and its comparison rules are fixed.</p><div class="st-actions"><button data-st="new">Set up the first study</button><button data-st="protocol">Read the protocol</button></div>`;status('Protocol revision '+spec.revision+' · no execution yet');}}catch(e){status(e.message);}}
 function renderIndex(){const filter=q('[data-st=search]').value.toLowerCase();q('.st-editions').innerHTML=editions.filter(e=>JSON.stringify(e).toLowerCase().includes(filter)).map(e=>`<button data-edition="${esc(e.edition_id)}">${esc(e.title||'Unavailable edition')}<small>${esc(e.tier||'')} · ${esc(e.status)} · ${e.completed_cases??e.completed_pairs??0}/${e.total_cases??e.total_pairs??'—'} ${e.summary_scope==='latest-publication'?'published ':''}${e.total_cases==null?'pairs':'cases'}</small><small>${esc(e.created_at?.slice(0,16)||'')} · ${esc(e.edition_id.slice(0,8))}</small></button>`).join('')||'<p>No matching editions.</p>';}
 async function view(id,reportId=null){const key=String(++generation);clearTimeout(timer);edition=id;pinnedReport=reportId;panel=null;if(w.contains(document.activeElement))q('[data-st=back]').focus({preventScroll:true});q('.st-article').hidden=true;q('.st-panel').hidden=true;q('.st-index').hidden=true;q('[data-st=index]').setAttribute('aria-expanded','false');status('Opening the study write-up…');try{const value=await post(request('view',{edition_id:id,report_id:reportId},key));if(!studyAccept(opened,generation,key,value))return;data=value;spec=value.manifest.protocol;render();progress(value.progress);schedule();}catch(e){if(key===String(generation))status(e.message);}}
 function progress(p){if(!p)return;status(p.description||p.status);q('.st-progress progress').hidden=p.status!=='running';q('.st-progress progress').value=p.fraction||0;q('[data-st=cancel]').hidden=!['running','cancelling'].includes(p.status);}
 function schedule(){clearTimeout(timer);if(opened&&!pinnedReport&&data?.progress?.status==='running')timer=setTimeout(poll,1100);}
 async function poll(){const key=String(generation),id=edition;try{const value=await post(request('status',{edition_id:id},key));if(!studyAccept(opened,generation,key,value)||edition!==id)return;const changed=JSON.stringify(value.cases.map(c=>[c.entry.status,c.attempts.length]))!==JSON.stringify(data.cases.map(c=>[c.entry.status,c.attempts.length]));data=value;progress(value.progress);if(changed&&!panel)render();schedule();}catch(e){if(key===String(generation))status(e.message);}}
 function table(headers,rows){return `<div class="st-table-wrap" tabindex="0"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
 function render(){if(!data)return;const restoreFocus=q('.st-panel').contains(document.activeElement);panel=null;q('.st-panel').hidden=true;q('.st-article').hidden=false;const m=data.manifest,p=m.protocol;
 if(data.uncertainty){renderUncertainty();return;}
 if(data.schema_version==='dispatch-lab/study-report/2'){renderField();if(restoreFocus)q('[data-st=back]').focus({preventScroll:true});return;}
 const rows=data.cases.map(c=>{const d=c.delta;return [`<button data-case="${esc(c.case_id)}">${esc(c.label)}</button>`,esc(c.entry.status),d?num(d.methane_kg):'—',d?num(d.battery_kwh,1):'—',esc(c.attempts.length)];});
 q('.st-article').innerHTML=`<div class="st-meta">Protocol ${p.revision} · ${esc(m.tier)} · ${p.tiers[m.tier].hours} hours · edition ${esc(m.edition_id.slice(0,8))}</div><h1>${esc(p.title)}</h1><p class="st-question">${esc(p.question)}</p><h2>Finding</h2><p class="st-finding">${esc(data.finding)}</p><p class="st-note">${data.completed_pairs}/${data.total_pairs} complete pairs. ${esc(data.interpretation_status)}.</p>${chart()}${data.interpretation?`<h2>Interpretation</h2>${data.interpretation.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}<p class="st-note">${esc(data.interpretation.author)} · ${esc(data.interpretation.scope)}</p>`:''}${computationOutcomes()}<h2>How the comparison works</h2><p>${esc(p.rationale)}</p><p>${esc(p.comparison)}</p><p>The capacity variants hold absolute battery power fixed. Initial SOC remains the same fraction; every resolved starting inventory is saved.</p><div class="st-actions"><button data-st="protocol">Protocol and assumptions</button><button data-st="configuration">Resolved configurations</button></div><h2>Every case</h2><p class="st-note">Differences are reserve minus baseline. Select a case to inspect both controllers, trace a metric or replay a recorded decision. Incomplete cases are shown without invented outcomes.</p>${table(['Case','Status','Δ methane / kg','Δ battery / kWh','Attempts'],rows)}<h2>What the evidence can support</h2><ul class="st-limit-list">${p.limits.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><p class="st-note">${esc(data.scope)} ${data.source_matches_current?'The execution source matches this app.':'The recorded source differs from this app; reproduction uses the original source.'}</p><h2>Reproduce or extend</h2><p>A reproduction creates a new edition with the original inputs and source. Repeating on the active plant applies this protocol to that run’s saved configuration. Earlier editions and report revisions remain available.</p><div class="st-actions"><button data-st="reproduce">Reproduce this edition</button><button data-st="repeat">Repeat on active plant</button><button data-st="resume">Run / resume</button><button data-st="fresh">Fresh trial, same inputs</button><button data-st="export">Download reproduction bundle</button><button data-st="history">Edition and report history</button></div><p class="st-note st-download"></p>`;if(restoreFocus)q('[data-st=back]').focus({preventScroll:true});
 }
 function renderField(){
  const m=data.manifest,p=m.protocol;
  const paired=data.comparisons.map(c=>[esc(c.condition+' / '+c.variant+' / '+c.seed),esc(c.arm_label),esc(c.status),num(c.delta.methane_kg),num(c.delta.total_eur),num(c.delta.crew_hours),num(c.delta.unfinished_orders,0),`<button data-case="${esc(c.baseline_case_id)}">Baseline</button> <button data-case="${esc(c.candidate_case_id)}">Arm</button>`]);
  const rows=data.cases.map(c=>[`<button data-case="${esc(c.case_id)}">${esc(c.label)}</button>`,esc(c.entry.status),num(c.outcomes?.methane_kg),num(c.outcomes?.service_expenditure_eur),num(c.outcomes?.remote_hours),esc(c.attempts.length)]);
  q('.st-article').innerHTML=`<div class="st-meta">Protocol ${p.revision} · ${esc(m.tier)} · ${p.tiers[m.tier].hours} hours · edition ${esc(m.edition_id.slice(0,8))}</div><h1>${esc(p.title)}</h1><p class="st-question">${esc(p.question)}</p><h2>Finding</h2><p class="st-finding">${esc(data.finding)}</p><p class="st-note">${data.completed_cases}/${data.total_cases} complete cases. ${esc(data.interpretation_status)}.</p>${data.interpretation?`<h2>Interpretation</h2>${data.interpretation.paragraphs.map(x=>`<p>${esc(x)}</p>`).join('')}<p class="st-note">${esc(data.interpretation.author)} · ${esc(data.interpretation.scope)}</p>`:''}${computationOutcomes()}<h2>How the comparison works</h2><p>${esc(p.rationale)}</p><p>${esc(p.comparison)}</p><div class="st-actions"><button data-st="protocol">Protocol and assumptions</button><button data-st="configuration">Resolved configurations</button></div><h2>Across completed seeds</h2>${table(['Condition / variant','Arm','Pairs','Mean Δ methane / kg','Methane range / kg','Mean Δ allocated / €','Priced pairs'],data.aggregate.map(g=>[esc(g.condition+' / '+g.variant),esc(p.arms.find(a=>a.id===g.arm_id)?.label||g.arm_id),esc(g.pairs),num(g.metrics.methane_kg.mean),(g.metrics.methane_kg.range||[]).map(v=>num(v)).join(' to '),num(g.metrics.total_eur.mean),esc(g.metrics.total_eur.available_pairs+'/'+g.metrics.total_eur.total_pairs)]))}<p class="st-note">Arithmetic means and observed ranges. Different conditions are kept separate; these are not confidence intervals.</p>${fieldQuestionOutcomes()}<h2>Matched outcomes</h2>${table(['Condition / variant / seed','Arm','Status','Δ methane / kg','Δ allocated / €','Δ crew / h','Δ unfinished','Inspect'],paired)}<p class="st-note">A dash means unavailable or undefined, including missing prices. It never means zero.</p><h2>Every case</h2>${table(['Case','Status','Methane / kg','Service expenditure / €','Remote / h','Attempts'],rows)}<h2>What the evidence can support</h2><ul class="st-limit-list">${p.limits.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="st-note">${esc(data.scope)} ${data.source_matches_current?'The execution source matches this app.':'Reproduction uses the saved original source.'}</p><h2>Reproduce or extend</h2><p>Each hardware arm has its own configuration and archive. A new edition preserves its parent and all earlier attempts. Repeating on the active plant retains the protocol’s declared basis-resolution rules.</p><div class="st-actions"><button data-st="reproduce">Reproduce this edition</button><button data-st="repeat">Repeat on active plant</button><button data-st="resume">Run / resume</button><button data-st="fresh">Fresh trial, same inputs</button><button data-st="export">Download reproduction bundle</button><button data-st="history">Edition and report history</button></div><p class="st-note st-download"></p>`;
 }
 function computationOutcomes(){const c=data.computation;if(!c)return '';return '<h2>Computation qualification</h2><p>'+esc(c.scope)+'</p>'+table(['Condition / plant / seed','Policy / budget','Repetitions','Repeatability','Methane range / kg','Process solve quality','Cases'],c.groups.map(g=>[esc(g.condition+' / '+g.variant+' / '+g.seed),esc(g.arm_id+' / '+g.budget),esc(g.completed_repetitions+'/'+g.expected_repetitions),esc(g.repeatability),(g.methane_range_kg||[]).map(v=>num(v,6)).join(' to ')||'Undefined',esc(g.solve_quality),g.case_ids.map(id=>`<button data-case="${esc(id)}">${esc(data.cases.find(c=>c.case_id===id)?.computation?.repetition||'Inspect')}</button>`).join(' ')]));}
 function fieldQuestionOutcomes(){const rows=data.question_outcomes||[];if(!rows.length)return '';return '<h2>Question-specific outcomes</h2>'+table(['Condition / variant','Arm','Outcome','Mean difference','Range','Available pairs'],rows.map(r=>[esc(r.condition+' / '+r.variant),esc(r.arm_id),esc(r.label),num(r.mean),(r.range||[]).map(v=>num(v)).join(' to '),esc(r.available_pairs+'/'+r.total_pairs)]))+'<p class="st-note">Candidate minus baseline over the same period. Missing measurements or mechanisms remain undefined; these outcomes do not establish a unique cause of a production difference.</p>';}
 function chart(){const cases=data.cases.filter(c=>c.delta);if(!cases.length)return '';const values=cases.map(c=>c.delta.methane_kg),extent=Math.max(1,...values.map(Math.abs)),y=v=>110-v/extent*85;return `<figure class="st-chart"><svg viewBox="0 0 850 230" role="img" aria-label="Paired methane differences; select a point to inspect its case"><line x1="60" y1="110" x2="830" y2="110"/><text x="0" y="29">+${num(extent,1)}</text><text x="20" y="114">0</text><text x="0" y="201">−${num(extent,1)}</text>${cases.map((c,i)=>`<circle cx="${75+i/Math.max(1,cases.length-1)*735}" cy="${y(c.delta.methane_kg)}" r="7" role="button" tabindex="0" data-case="${esc(c.case_id)}" aria-label="${esc(c.label)}: ${num(c.delta.methane_kg)} kg difference"><title>${esc(c.label)} · ${num(c.delta.methane_kg)} kg</title></circle>`).join('')}<text x="60" y="226">Completed matched cases</text></svg><p>Paired methane difference / kg CH₄. Above zero: more methane with the terminal battery value. These points are observed differences, not confidence intervals.</p></figure>`;}
 function showPanel(name,body){panel=name;q('.st-article').hidden=true;q('.st-panel').hidden=false;q('.st-panel-body').innerHTML=body;q('[data-st=close-panel]').focus({preventScroll:true});w.scrollTop=0;}
 function rowsObject(object){return Object.entries(object).map(([k,v])=>[esc(k),esc(typeof v==='object'?JSON.stringify(v):v)]);}
 function reportingDetails(){const r=data?.reporting;if(!r)return '';return `<h2>Report derivation</h2><p>${esc(r.scope)} Ended procedures can remain unverified even after physical work finishes.</p>${table(['Identity','Recorded value'],rowsObject({implementation:r.implementation_id,reporting_source:r.source_hash,execution_source:data.manifest.source_hash,reporting_capsule:r.source_capsule_sha256}))}${table(['Derived metric','Definition'],rowsObject(r.metric_definitions))}`;}
 function protocolPanel(){const p=data?.manifest.protocol||spec;showPanel('protocol',`<h1>Protocol and assumptions</h1><p>${esc(p.question)}</p><p>${esc(p.policy_tuning)}</p>${table(['Rule','Definition'],rowsObject(p.resolution))}<h2>Policy definitions</h2>${table(['Controller','Frozen policy'],rowsObject(p.policies))}<h2>Outcome calculations</h2>${table(['Metric','Definition'],rowsObject(p.metric_definitions))}${reportingDetails()}<h2>Completeness checks</h2><ul>${p.checks.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p class="st-note">Revision ${p.revision}; ${esc(p.review.scope)}</p>`);}
 function configuration(){if(data.schema_version==='dispatch-lab/study-report/2'){showPanel('config',`<h1>Resolved configurations</h1><p>${esc(data.manifest.protocol.resolution.plant_basis)}</p><p>${esc(data.manifest.protocol.resolution.variants)}</p><p>Each arm is a separate run. The matching signature includes shared plant, weather, fault, sensor and environmental-loss inputs.</p>${table(['Case','Matched group','Input signature','Weather'],data.cases.map(c=>[esc(c.label),esc(c.group_id),esc(c.matching_inputs_hash),esc(c.weather_hash||c.input_error||'Missing')]))}<h2>Every change from the selected basis</h2>${data.cases.map(c=>`<h3>${esc(c.label)}</h3>${table(['Parameter','Basis','Resolved'],c.changes_from_basis.map(d=>[esc(d.parameter),esc(JSON.stringify(d.before)),esc(JSON.stringify(d.after))]))}<pre>${esc(JSON.stringify(c.config,null,2))}</pre>`).join('')}`);return;}showPanel('config',`<h1>Resolved configurations</h1><p>Each case stores complete values; reruns do not inherit application defaults. Battery capacity changes preserve absolute power and the initial charge fraction.</p>${table(['Case','Capacity / kWh','Power / kW','Starting energy / kWh'],data.cases.map(c=>[esc(c.label),num(c.resolved_battery.capacity_kwh,1),num(c.resolved_battery.power_kw,1),num(c.resolved_battery.initial_kwh,1)]))}<h2>Basis changes from the reference fixture</h2>${table(['Parameter','Reference','Basis'],data.manifest.basis_changes.map(d=>[esc(d.parameter),esc(JSON.stringify(d.before)),esc(JSON.stringify(d.after))]))}<h2>Origin of the plant basis</h2><pre>${esc(JSON.stringify(data.manifest.basis_origin||'Protocol reference fixture',null,2))}</pre><h2>Exact case inputs</h2>${data.cases.map(c=>`<h3>${esc(c.label)}</h3><pre>${esc(JSON.stringify(c.config,null,2))}</pre>`).join('')}`);}
 function casePanel(id){const c=data.cases.find(c=>c.case_id===id);if(!c)return;const e=c.entry;let body=`<h1>${esc(c.label)}</h1><p>${esc(e.status)} · ${esc(e.error||'Original decisions and report prices are frozen.')}</p>`;
 if(e.metrics){body+=table(['Controller','Methane / kg','Ending battery / kWh','H₂ / kg','CO₂ / kg','Reactor / °C','Trips','Allocated / €','Contribution / €'],Object.entries(e.metrics).map(([n,m])=>[esc(n),`<button data-trace="methane_kg" data-case-id="${esc(id)}" data-controller="${esc(n)}">${num(m.methane_kg)}</button>`,`<button data-trace="battery_kwh" data-case-id="${esc(id)}" data-controller="${esc(n)}">${num(m.ending?.battery_kwh,1)}</button>`,num(m.ending?.h2_kg),num(m.ending?.co2_kg),num(m.ending?.temperature_c,1),esc(m.forced_downtime_hours),num(m.total_eur),num(m.assumed_contribution_eur)]));body+=data.schema_version==='dispatch-lab/study-report/2'?'<h2>Recorded decisions</h2><p>Replay this arm from its recorded initial interval. All later observations, work and recovery remain available in the player; this starting point is not a causal ranking.</p>':'<h2>Recorded decisions</h2><p>Inspect the first interval with different applied battery discharge, if one exists. This selection rule is fixed and does not establish a unique cause of the final output difference.</p>';body+=Object.keys(e.metrics).map(n=>{const event=e.events?.find(v=>v.controller===n),hour=event?.hour??0;return `<div class="st-actions"><button data-replay="${esc(id)}" data-controller="${esc(n)}" data-hour="${hour}">Replay ${esc(n)} · interval ${hour}</button></div>${event?`<p class="st-note">Discharge ${num(event.discharge_kw)} kW; ending energy ${num(event.energy_kwh)} kWh.</p>`:''}`;}).join('');body+=table(['Controller','Utilisation / %','Curtailed / kWh','Reactor starts','Electrolyser starts'],Object.entries(e.metrics).map(([n,m])=>[esc(n),num(m.utilisation*100,1),num(m.curtailed_kwh),esc(m.reactor_starts),esc(m.electrolyser_starts)]));body+=table(['Controller','Limited solves','Fallbacks'],Object.entries(e.metrics).map(([n,m])=>[esc(n),esc(m.limited_solves),esc(m.fallbacks)]));}
 if(c.uncertainty_world){body+=`<h2>Original uncertainty realization</h2><p>World ${esc(c.uncertainty_world.world_id)} · event seed ${esc(c.seed)}. Physical values below are retrospective truth; hidden values were not given to the controller.</p>${table(['Parameter','Physical value','Original controller assumption','Evidence'],c.uncertainty_world.draws.map(d=>[esc(d.path),esc(JSON.stringify(d.value)),esc(JSON.stringify(d.visibility==='hidden'?d.nominal:d.value)),esc(d.source)]))}`;}
 if(c.outcomes){const o=c.outcomes;body+=`<h2>Service work and costs</h2>${table(['Metric','Recorded value'],[['Allocated service / €',`<button data-trace="service_allocated_eur" data-case-id="${esc(id)}" data-controller="${esc(c.controller)}">${num(o.service_allocated_eur)}</button>`],['Action-dependent service / €',`<button data-trace="service_decision_eur" data-case-id="${esc(id)}" data-controller="${esc(c.controller)}">${num(o.service_decision_eur)}</button>`],['Modelled service expenditure / €',`<button data-trace="service_expenditure_eur" data-case-id="${esc(id)}" data-controller="${esc(c.controller)}">${num(o.service_expenditure_eur)}</button>`],['Site visits',num(o.site_visits,0)],['Committed crew / h',`<button data-trace="crew_hours" data-case-id="${esc(id)}" data-controller="${esc(c.controller)}">${num(o.crew_hours)}</button>`],['Remote work / h',`<button data-trace="remote_hours" data-case-id="${esc(id)}" data-controller="${esc(c.controller)}">${num(o.remote_hours)}</button>`],['Unfinished work orders',num(o.unfinished_orders,0)],[data.reporting&&(e.metrics[c.controller].service_outcomes_available||e.metrics[c.controller].service_outcomes)?'Ended restoration procedures, not verified':'Completed, not verified',num(o.completed_unverified_orders,0)]] )}<h2>Ending service resources and work</h2>${table(['Resource','Ending','Reserved','Unit'],(e.metrics[c.controller].service_work?.executive?.resources||[]).filter(r=>r.resource.startsWith('stock:')||r.resource.startsWith('upstream:')).map(r=>[esc(r.resource),num(r.ending),num(r.reserved),esc(r.unit)]))}${table(['Work request','Status','Completed at / h','Verified at / h'],(e.metrics[c.controller].service_work?.orders||[]).map(r=>[esc(r.kind),esc(r.status),num(r.completed_hour),num(r.verified_at_hour)]))}<button data-service-record="${esc(id)}">Inspect full service record</button>`;}
 body+=`<h2>Attempt history</h2>${table(['Attempt','Status','Error'],c.attempts.map(a=>[esc(a.attempt_id),esc(a.status),esc(a.error||'')]))}`;if(e.numerical_comparison)body+=`<h2>Numerical rerun differences</h2><pre>${esc(JSON.stringify(e.numerical_comparison,null,2))}</pre>`;showPanel('case',body);}
 async function traceMetric(el){const key=String(++generation);clearTimeout(timer);status('Loading the recorded calculation…');try{const value=await post(request('trace',{edition_id:edition,case_id:el.dataset.caseId,controller:el.dataset.controller,metric:el.dataset.trace,attempt_id:data.cases.find(c=>c.case_id===el.dataset.caseId)?.entry.attempt_id},key));if(!studyAccept(opened,generation,key,value))return;const t=value.trace;showPanel('trace',`<h1>Trace calculation</h1><p>${esc(t.definition)}</p><p class="st-finding">${num(t.value)} ${esc(t.unit)}</p><p>${esc(t.note)}</p>${table(['Interval / term','Operand','Unit'],t.operands.map(o=>[esc(o.interval),num(o.value,5),esc(o.unit)]))}<h2>Identity and assumptions</h2>${table(['Record','Value'],rowsObject({controller:t.controller,run:t.run_id,source:t.source_hash,weather:t.weather_hash,policy:t.policy,original_decision_cost_version:t.original_decision_cost_version,original_service_cost_version:t.original_service_cost_version,independent_audit:t.audit,uncertainty_world:t.uncertainty_world}))}${t.calculation?`<h2>Calculation operands and sources</h2><pre>${esc(JSON.stringify(t.calculation,null,2))}</pre>`:''}`);status('Recorded calculation loaded');schedule();}catch(e){status(e.message);}}
 function newStudy(basis='reference',keepProtocol=false){generation++;clearTimeout(timer);previewReady=false;newParent=keepProtocol?edition:null;newSpec=keepProtocol?data.manifest.protocol:protocolCatalogue.find(p=>p.study_id===spec?.study_id)||protocolCatalogue[0];
 showPanel('new',`<h1>${edition?'Repeat or extend the study':'Run the first study'}</h1><p>Choose the question, plant basis and execution size. Existing editions remain unchanged.</p><div class="st-form"><label for="study-protocol">Study question</label><select id="study-protocol" data-st="protocol-choice" ${keepProtocol?'disabled':''}>${(keepProtocol?[newSpec]:protocolCatalogue).map(p=>`<option value="${esc(p.study_id)}">${esc(p.title)}</option>`).join('')}</select><label for="study-basis">Plant basis</label><select id="study-basis" data-st="basis"><option value="reference">Original reference fixture</option><option value="current-plant">Active run’s saved plant and assumptions</option></select><label for="study-tier">Protocol execution size</label><select id="study-tier" data-st="tier"></select><div class="st-preview"></div><div class="st-actions"><button data-st="start" disabled>Start new study edition</button></div></div>`);q('[data-st=protocol-choice]').value=newSpec.study_id;q('[data-st=basis]').value=basis;tierOptions();preview();}
 function tierOptions(){q('[data-st=tier]').innerHTML=Object.keys(newSpec.tiers).map(k=>`<option value="${esc(k)}">${esc(k.charAt(0).toUpperCase()+k.slice(1))}</option>`).join('');q('[data-st=tier]').value='reference';}
 async function preview(){const key=String(++generation);previewReady=false;q('[data-st=start]').disabled=true;q('.st-preview').textContent='Resolving complete inputs…';try{const value=await post(request('preview',{edition_id:newParent,protocol_id:newParent?null:newSpec.study_id,basis:q('[data-st=basis]').value,tier:q('[data-st=tier]').value},key));if(!studyAccept(opened,generation,key,value)||panel!=='new')return;const p=value.preview;q('.st-preview').innerHTML=p.kind==='field'?`<p>${p.cases} separate cases · ${p.pairs} matched comparisons · ${p.hours} hours per trace.</p><p>${esc(p.purpose)}</p><p>${esc(p.resolution.plant_basis)}</p><p>${esc(p.resolution.variants)}</p>${table(['Service package','Controller','Declared arm changes'],p.arms.map(a=>[esc(a.label),esc(a.controller),esc(JSON.stringify(a.patch))]))}<p>Shared weather, fault and environmental-loss inputs are checked for every matched group. Complete configurations and all basis changes are saved before execution.</p>`:`<p>${p.pairs} paired cases · ${p.policies.length} controllers · ${p.hours} hours per trace.</p><p>${esc(p.purpose)}</p>${table(['Capacity / kWh','Power / kW','Starting energy / kWh'],p.batteries.map(b=>[num(b.capacity_kwh,1),num(b.power_kw,1),num(b.initial_kwh,1)]))}<p>Power stays fixed; initial SOC fraction is preserved. Weather is frozen synthetic data with normal and overestimated forecasts. No equipment faults are injected in this protocol.</p>`;q('.st-preview').innerHTML+=(p.computation?`<p>${p.computation.repetitions} repetitions per unchanged seed. These are computational repeats, not new environmental samples.</p>${table(['Budget','Process / s','Service / s','Investigation / s'],p.computation.budgets.map(b=>[esc(b.id),num(b.process_seconds),num(b.service_seconds),num(b.investigation_seconds)]))}`:'');q('.st-preview').innerHTML+=`${p.basis_origin?.resolved_legacy_fields?.length?`<p>Legacy archive: the current compatibility defaults supply ${esc(p.basis_origin.resolved_legacy_fields.map(d=>d.parameter).join(', '))}. These additions and the original run identity will be recorded in the edition.</p>`:''}<p class="st-note">${p.basis_changes.length} basis fields differ from the original reference. Complete values are saved before execution.</p>`;previewReady=true;q('[data-st=start]').disabled=false;}catch(e){if(key===String(generation))q('.st-preview').textContent=e.message;}}
 async function action(op,extra={}){const key=String(++generation);clearTimeout(timer);status(op==='export'?'Preparing the portable study bundle…':'Submitting study operation…');try{const value=await post(request(op,{edition_id:edition,report_id:data?.report_id,...extra},key));if(!studyAccept(opened,generation,key,value))return;if(value.download_url){const link=q('.st-download');if(link)link.innerHTML=`<a href="${esc(value.download_url)}" download>Download study, inputs, source and recorded playback</a>`;status('Reproduction bundle ready');}else if(op==='cancel'){progress(value.progress);if(data)data.progress={status:'running'};schedule();}else{pinnedReport=null;data=value;edition=value.edition_id;render();progress(value.progress);schedule();}}catch(e){if(key===String(generation))status(e.message);}}
 async function loadServiceRecord(id){
  const c=data.cases.find(c=>c.case_id===id);if(!c)return;
  const key=String(++generation),selectedEdition=edition;clearTimeout(timer);
  const heading=`<h1>Recorded service state</h1><p>${esc(c.label)}</p><button data-case="${esc(c.case_id)}">Return to this case</button>`;
  showPanel('service-record',heading+'<p role="status">Loading this original service record…</p>');status('Loading the selected case record…');
  try{const value=await post(request('service-record',{edition_id:selectedEdition,report_id:data.report_id,case_id:id,attempt_id:c.entry.attempt_id,controller:c.controller},key));
   if(!studyAccept(opened,generation,key,value)||panel!=='service-record'||edition!==selectedEdition)return;
   const r=value.service_record;
   if(r.edition_id!==selectedEdition||(r.report_id??null)!==(data.report_id??null)||r.case_id!==id||r.attempt_id!==c.entry.attempt_id||r.controller!==c.controller)throw Error('Service record does not match the selected case');
   q('.st-panel-body [role=status]').outerHTML=`<p class="st-note">${esc(r.scope)}</p><pre>${esc(JSON.stringify(r.work,null,2))}</pre>`;status('Original service record loaded');
  }catch(e){if(studyAccept(opened,generation,key,{key})&&panel==='service-record'){q('.st-panel-body [role=status]').textContent=e.message;status('Service record unavailable');}}
 }
 let uCatalogue=null,uDraft=null,uPreview=null;
 function uInvalidate(){uPreview=null;generation++;if(q('[data-u=start]'))q('[data-u=start]').disabled=true;if(q('.u-preview'))q('.u-preview').textContent='Inputs changed. Preview these assumptions before running.';}
 async function uncertaintySetup(){const key=String(++generation);clearTimeout(timer);showPanel('uncertainty','<h1>Explore uncertainty</h1><p role="status">Loading the active plant’s complete assumption catalogue…</p>');try{const v=await post(request('uncertainty-catalogue',{},key));if(!studyAccept(opened,generation,key,v)||panel!=='uncertainty')return;uCatalogue=v.catalogue;uDraft=v.specification;uDraft.blocks=[];uDraft.rationale='Explore explicitly selected assumptions on the active plant; support is conditional and does not establish calibration.';uDraft.worlds=12;uDraft.design='space-filling';uPreview=null;uEditor();}catch(e){if(key===String(generation))status(e.message);}}
 function uOptions(){const term=(q('[data-u=search]')?.value||'').toLowerCase();const params=uCatalogue.parameters.filter(p=>JSON.stringify([p.label,p.path,p.group]).toLowerCase().includes(term));q('[data-u=parameter]').innerHTML=params.flatMap(p=>Object.entries(p.values).map(([path,v])=>`<option value="${esc(path)}">${esc(p.group+' · '+p.label+' · '+path+' = '+JSON.stringify(v))}</option>`)).join('');uParameter();}
 function uParameter(){const path=q('[data-u=parameter]').value,p=uCatalogue.parameters.find(p=>Object.hasOwn(p.values,path));q('.u-basis').innerHTML=p?`<p>${esc(p.representation)} · ${esc(p.evidence)}</p><p>${esc(p.mechanism_scope)}</p><p>Evidence needed: ${esc(p.evidence_needed)}</p>`:'<p>No active parameter matches. Optional systems must first be configured in an experiment; exploring uncertainty never enables them silently.</p>';q('[data-u=visibility]').value=p?.hidden_supported?'hidden':'disclosed';q('[data-u=visibility] option[value=hidden]').disabled=!p?.hidden_supported;if(p){q('[data-u=values]').value=(p.suggested_values||[p.values[path]]).map(x=>JSON.stringify(x)).join(', ');q('[data-u=source]').value=p.suggested_values?'Assumption review '+uCatalogue.registry_edition:'User-authored stress assumption; evidence gap';}}
 function uEditor(){showPanel('uncertainty',`<h1>What could change the conclusion?</h1><p>Explore the active plant. Each trace uses one coherent world; all three controllers share its events. Nothing changes the run you came from.</p><p class="st-note">${esc(uCatalogue.scope)}</p><div class="st-actions"><button data-u="presets">Use registered stress tests</button><button data-u="clear">Clear selected blocks</button><button data-u="download">Save specification</button><label>Load specification<input type="file" data-u="import" accept="application/json,.json"></label></div><h2>Choose an assumption</h2><label>Find a component, support resource, price or policy<input type="search" data-u="search" placeholder="Temperature, robot, labour, forecast…"></label><label>Active parameter<select data-u="parameter"></select></label><div class="u-basis"></div><p class="st-note">${uCatalogue.parameters.length} registered parameters; ${uCatalogue.parameters.filter(p=>p.active).length} present in this setup. Omitted mechanisms and unknown capabilities remain evidence gaps.</p><div class="u-grid"><label>Representation<select data-u="kind"><option value="values">Explicit scenario values</option><option value="bounds">Plausible bounds, no probabilities</option><option value="uniform">Assumed uniform probability</option><option value="triangular">Assumed triangular probability</option></select></label><label>Values, or lower / upper / mode<input data-u="values" placeholder="0.85, 0.9, 0.95"></label><label>Controller knowledge<select data-u="visibility"><option value="hidden">Keep original controller assumption</option><option value="disclosed">Disclose this assumption to controller</option></select></label><label>Evidence or explicit gap<input data-u="source"></label><label>Why this support applies<input data-u="reason" value="Exploratory sensitivity; support has not been calibrated for this plant."></label></div><button data-u="add">Add parameter block</button><p class="st-note">Dependent parameters belong in the same joint block. Import a specification with complete joint rows and their evidence; rows are always sampled together. No correlation or distribution is inferred from these bounds.</p><div class="u-blocks"></div><h2>Observation uncertainty</h2><p>Additive uncertainty is optional and uses channel units. Persistent bias and drift are separate from independent reading noise; the controller sees error budgets, never the sampled errors. Existing configured sensor noise still applies.</p><div class="u-grid"><label>Channel<select data-u="channel"><option value="power_kw">Electrical power / kW</option><option value="hydrogen_flow_kg">Hydrogen inflow / kg per interval</option><option value="h2_inventory_kg">Hydrogen inventory / kg</option><option value="h2_outflow_kg">Hydrogen outflow / kg per interval</option><option value="battery_kwh">Battery inventory / kWh</option><option value="co2_kg">CO₂ inventory / kg</option><option value="temperature_c">Reactor temperature / °C</option></select></label><label>Reading standard deviation<input data-u="noise" type="number" min="0" value="0" step="any"></label><label>Persistent bias standard deviation<input data-u="bias" type="number" min="0" value="0" step="any"></label><label>Drift-rate standard deviation per hour<input data-u="drift" type="number" min="0" value="0" step="any"></label><label>Observation evidence or gap<input data-u="sensor-source" value="User-assumed Gaussian errors; not calibrated"></label></div><button data-u="measure">Set channel model</button><div class="u-measurements"></div><h2>Learning from observations</h2><label>Performance estimates<select data-u="adaptation"><option value="off">Original fixed assumptions</option><option value="fixed">Record estimates without adapting</option><option value="adaptive">Adapt solar and cleaning estimates</option></select></label><p>Uses observed power, irradiance and the selected surface observation model. Bounded service mode adds explicit reference and surface errors. This is an illustrative estimator, not a calibrated posterior. Editing the full specification exposes its gain, evidence threshold and support.</p><h2>Service decisions under uncertainty</h2><label>Planning and observations<select data-u="autonomy"><option value="off">Existing service model</option><option value="fixed">Bounded execution · fixed planning assumptions</option><option value="adaptive">Learn service durations from observations</option><option value="risk-aware">Learn and plan across possible outcomes</option></select></label><p>Reserves resources through the declared duration bounds, including return. Actual timing stays private. Requires enabled fractional services; planning across outcomes also requires a coordinated MPC service policy. Complete bounds, observation budgets and future support scenarios are editable in the saved specification.</p><h2>Comparison design</h2><div class="u-grid"><label>Design<select data-u="design"><option value="space-filling">Joint space-filling scenarios</option><option value="screening">Matched one-block screening</option><option value="factorial">Complete factorial scenarios</option><option value="probability">Sample explicit probabilities</option></select></label><label>World budget<input type="number" data-u="worlds" min="1" max="128" value="${uDraft.worlds}"></label><label>Sampling seed<input type="number" data-u="seed" min="0" value="${uDraft.seed}"></label><label>Event seeds<input data-u="seeds" value="${esc(uDraft.inner_seeds.join(', '))}"></label><label>Scope of this experiment<textarea data-u="rationale">${esc(uDraft.rationale)}</textarea></label></div><p>World parameters remain fixed through a run. Event seeds generate weather and observations through the existing time-aware mechanisms. Solver repeats remain numerical repeats. Study ranges do not become confidence intervals.</p><div class="st-actions"><button data-u="preview">Preview resolved worlds</button><button data-u="start" disabled>Run reviewed comparison</button></div><div class="u-preview" role="status"></div>`);q('[data-u=design]').value=uDraft.design;q('[data-u=adaptation]').value=uDraft.adaptation?.mode||'off';q('[data-u=autonomy]').value=uDraft.autonomy?.mode||'off';uOptions();uBlocks();uMeasurements();}
 function uBlocks(){q('.u-blocks').innerHTML=`<h3>${uDraft.blocks.length} selected blocks</h3>`+table(['Parameter block','Representation','Knowledge','Remove'],uDraft.blocks.map((b,i)=>[esc(b.paths.join(', ')),esc(b.kind+' · '+JSON.stringify(b.rows||[b.low,b.high,b.mode].filter(x=>x!=null))),esc(b.visibility),`<button data-u="remove" data-index="${i}" aria-label="Remove ${esc(b.id)}">Remove</button>`]));}
 function uMeasurements(){q('.u-measurements').innerHTML=table(['Channel','Reading SD','Bias SD','Drift SD/h',''],Object.entries(uDraft.measurements||{}).map(([k,v])=>[esc(k),esc(v.noise_sd),esc(v.bias_sd),esc(v.drift_sd_per_hour),`<button data-u="unmeasure" data-channel="${esc(k)}">Remove</button>`]));}
 function uRead(){const draft={...uDraft};const auto=q('[data-u=autonomy]').value;if(auto==='off'){delete draft.autonomy;delete draft.support_events;}else draft.autonomy={...(draft.autonomy||uCatalogue.autonomy.defaults),mode:auto};const mode=q('[data-u=adaptation]').value;if(mode==='off')delete draft.adaptation;else draft.adaptation={...(draft.adaptation||uCatalogue.adaptation.defaults),mode};return {...draft,design:q('[data-u=design]').value,worlds:Number(q('[data-u=worlds]').value),seed:Number(q('[data-u=seed]').value),inner_seeds:q('[data-u=seeds]').value.split(',').filter(x=>x.trim()).map(x=>Number(x.trim())),rationale:q('[data-u=rationale]').value};}
 async function uAction(el){const action=el.dataset.u;try{if(action==='open'){await uncertaintySetup();return;}if(action==='add'){const path=q('[data-u=parameter]').value;if(!path)throw Error('Select an active parameter');const kind=q('[data-u=kind]').value;const values=q('[data-u=values]').value.split(',').map(s=>{try{return JSON.parse(s.trim());}catch{return s.trim();}});if(values.some(v=>v===''))throw Error('Supply explicit values');const b={id:path,paths:[path],kind,visibility:q('[data-u=visibility]').value,source:q('[data-u=source]').value,rationale:q('[data-u=reason]').value};if(kind==='values')b.rows=values.map(v=>[v]);else{if(values.length!==(kind==='triangular'?3:2))throw Error('Supply lower, upper'+(kind==='triangular'?' and mode':''));[b.low,b.high,b.mode]=values;if(kind!=='triangular')delete b.mode;}uDraft.blocks=uDraft.blocks.filter(b=>!b.paths.includes(path));uDraft.blocks.push(b);uInvalidate();uBlocks();}else if(action==='remove'){uDraft.blocks.splice(Number(el.dataset.index),1);uInvalidate();uBlocks();}else if(action==='clear'){uDraft.blocks=[];uInvalidate();uBlocks();}else if(action==='presets'){const key=String(++generation);const v=await post(request('uncertainty-catalogue',{},key));if(!studyAccept(opened,generation,key,v)||panel!=='uncertainty')return;uDraft=v.specification;uPreview=null;uEditor();}else if(action==='measure'){const channel=q('[data-u=channel]').value;uDraft.measurements??={};uDraft.measurements[channel]={noise_sd:Number(q('[data-u=noise]').value),bias_sd:Number(q('[data-u=bias]').value),drift_sd_per_hour:Number(q('[data-u=drift]').value),source:q('[data-u=sensor-source]').value};uInvalidate();uMeasurements();}else if(action==='unmeasure'){delete uDraft.measurements[el.dataset.channel];uInvalidate();uMeasurements();}else if(action==='download'){const blob=new Blob([JSON.stringify(uRead(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='dispatch-uncertainty.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}else if(action==='preview'){const key=String(++generation);uPreview=null;q('[data-u=start]').disabled=true;q('.u-preview').textContent='Resolving and checking every world…';const draft=uRead();const v=await post(request('uncertainty-preview',{uncertainty:draft},key));if(!studyAccept(opened,generation,key,v)||panel!=='uncertainty')return;uDraft=draft;uPreview=v.preview_hash;q('.u-preview').innerHTML=`<p>${v.worlds} worlds × ${draft.inner_seeds.length} event seeds = ${v.cases} cases, each with ${v.controllers.length} controllers and ${v.hours} hours.</p><p>${v.invalid.length} invalid inputs will be recorded without execution. ${draft.design==='probability'?'Distributions are assumed as declared.':'The outputs will be labelled as scenario ranges, not probabilities.'}</p>${v.invalid.length?table(['Case','Violated condition'],v.invalid.map(x=>[esc(x.label),esc(x.error)])):''}<p>${esc(uCatalogue.knowledge_boundary)}</p>${table(['World','Resolved parameter','Physical value','Controller assumption'],v.draws.flatMap(w=>w.draws.map(d=>[esc(w.index+1),esc(d.path),esc(JSON.stringify(d.value)),esc(JSON.stringify(d.visibility==='hidden'?d.nominal:d.value))])))}`;q('[data-u=start]').disabled=false;}else if(action==='start'&&uPreview){await actionUncertaintyStart();}}catch(e){status(e.message);if(q('.u-preview'))q('.u-preview').textContent=e.message;}}
 async function actionUncertaintyStart(){const key=String(++generation);q('[data-u=start]').disabled=true;status('Saving the reviewed worlds and starting the isolated study worker…');const v=await post(request('uncertainty-create',{uncertainty:uRead(),preview_hash:uPreview},key));if(!studyAccept(opened,generation,key,v))return;data=v;edition=v.edition_id;pinnedReport=null;render();progress(v.progress);schedule();}
 function uEnvelope(key){const series=data.uncertainty.trajectory_ranges||{};q('.u-envelope').innerHTML=Object.entries(series).map(([name,outputs])=>{const rows=outputs[key]||[];if(!rows.length)return '';const lo=Math.min(...rows.map(r=>r.minimum)),hi=Math.max(...rows.map(r=>r.maximum)),n=Math.max(...rows.map(r=>r.hour)),x=h=>48+(h/n)*600,y=v=>170-(v-lo)/(hi-lo||1)*140;const path=rows.map((r,i)=>`${i?'L':'M'}${x(r.hour)},${y(r.maximum)}`).join(' ')+rows.slice().reverse().map(r=>`L${x(r.hour)},${y(r.minimum)}`).join(' ')+'Z';return `<figure><figcaption>${esc(name)} · ${num(lo)} to ${num(hi)} · ${Math.min(...rows.map(r=>r.cases))}–${Math.max(...rows.map(r=>r.cases))} complete cases per interval</figcaption><svg viewBox="0 0 690 210" role="img" aria-label="${esc(name+' '+key+' observed range by elapsed hour')}"><path d="M48 20V170H650" fill="none" stroke="currentColor" opacity=".5"/><path d="${path}" fill="currentColor" fill-opacity=".15" stroke="currentColor"/><text x="48" y="198" fill="currentColor" font-size="12">0 h</text><text x="620" y="198" fill="currentColor" font-size="12">${n} h</text><text x="48" y="15" fill="currentColor" font-size="12">${num(hi)}</text></svg></figure>`;}).join('')||'<p>No complete trajectory evidence yet.</p>';}
 function renderUncertainty(){const u=data.uncertainty;const summaries=u.summaries.map(s=>{const d=s.metrics.methane_kg.paired_cases;return `<article><h2>${esc(s.candidate)} compared with Greedy</h2><p class="st-finding">${num(d.minimum)} to ${num(d.maximum)} kg methane difference</p><p>${s.complete_pairs} complete pairs · ${s.complete_worlds} worlds with every event seed · ${s.rank_reversal?'The output ranking reverses across evaluated cases.':'No output ranking reversal observed in complete cases.'}</p>${table(['Outcome difference','Observed case minimum','Observed case maximum','Complete-world mean minimum','Complete-world mean maximum'],Object.entries(s.metrics).map(([k,v])=>[esc(k.replaceAll('_',' ')),num(v.paired_cases.minimum),num(v.paired_cases.maximum),num(v.world_means.minimum),num(v.world_means.maximum)]))}${u.specification.design==='probability'?`<p>Conditional finite-sample quantiles of complete-world mean differences; not confidence bounds.</p>${table(['Metric','5th percentile','Median','95th percentile'],Object.entries(s.metrics).map(([k,v])=>[esc(k),num(v.world_means.sample_quantiles?.p05),num(v.world_means.sample_quantiles?.p50),num(v.world_means.sample_quantiles?.p95)]))}`:''}</article>`;}).join('');q('.st-article').innerHTML=`<h1>${esc(data.manifest.protocol.title)}</h1><p>${esc(data.finding)}</p><p class="st-note">${esc(data.scope)}</p><p>${esc(u.specification.rationale)}</p>${summaries}<h2>How states diverge over time</h2><p>Observed envelopes across complete cases. Each plant playback remains a single realization; the envelope is not an operating trajectory or a confidence band.</p><label>State or flow<select data-u=trajectory><option value=battery_kwh>Battery / kWh</option><option value=h2_kg>Hydrogen / kg</option><option value=co2_kg>CO₂ / kg</option><option value=temperature_c>Reactor / °C</option><option value=methane_kg>Methane / kg per interval</option></select></label><div class=u-envelope></div><h2>What most changed the comparison?</h2><p>Matched one-block screening identifies evidence priorities; this does not measure interactions or assign a monetary value to new information.</p>${table(['Block','Controller','Largest change in methane advantage / kg','Matched cases'],u.screening.map(r=>[esc(r.block),esc(r.candidate),num(r.maximum_absolute_change_kg),esc(r.matched_cases)]))}<h2>Every recorded world</h2>${table(['Case','Status','Reason'],data.cases.map(c=>[`<button data-case="${esc(c.case_id)}">${esc(c.label)}</button>`,esc(c.entry.status),esc(c.entry.error||c.input_error||'')]))}<h2>Coverage and limits</h2><p>${u.unsampled_assumptions.length} active uncertain assumptions were held fixed. Their uncertainty has not disappeared.</p><div class="st-actions"><button data-u="coverage">Inspect unsampled assumptions</button><button data-st="configuration">Resolved configurations</button></div><p>${esc(u.sampling_scope)}</p><div class="st-actions"><button data-st="resume">Run / resume</button><button data-st="fresh">Fresh numerical trial</button><button data-st="reproduce">Reproduce this edition</button><button data-u="open">Design another uncertainty study</button><button data-st="export">Download reproduction bundle</button><button data-st="history">Report history</button></div><p class="st-note st-download"></p>`;uEnvelope('battery_kwh');}
 w.addEventListener('click',e=>{e.stopPropagation();const el=e.target.closest('button,[data-case]');if(!el)return;if(el.dataset.u){if(el.dataset.u==='coverage')showPanel('coverage',`<h1>Uncertainty held fixed</h1><p>These assumptions still need evidence or explicit stress support.</p><ul>${data.uncertainty.unsampled_assumptions.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>`);else uAction(el);return;}if(el.dataset.publication){view(edition,el.dataset.publication);return;}if(el.dataset.edition){view(el.dataset.edition);return;}if(el.dataset.serviceRecord){loadServiceRecord(el.dataset.serviceRecord);return;}if(el.dataset.case){casePanel(el.dataset.case);return;}if(el.dataset.trace){traceMetric(el);return;}if(el.dataset.replay){pause();status('Opening recorded playback…');replay({edition_id:edition,case_id:el.dataset.replay,attempt_id:data.cases.find(c=>c.case_id===el.dataset.replay)?.entry.attempt_id,report_id:data.report_id,controller:el.dataset.controller,hour:Number(el.dataset.hour),component:data.schema_version==='dispatch-lab/study-report/2'?'electrolyser':'battery'});return;}switch(el.dataset.st){case'back':close();break;case'index':q('.st-index').hidden=!q('.st-index').hidden;el.setAttribute('aria-expanded',String(!q('.st-index').hidden));if(!q('.st-index').hidden){q('[data-st=search]').focus();const key=String(generation);post(request('list',{},key)).then(v=>{if(studyAccept(opened,generation,key,v)){editions=v.editions;renderIndex();}}).catch(e=>{if(key===String(generation))status(e.message);});}break;case'new':newStudy();break;case'repeat':newStudy('current-plant',true);break;case'protocol':protocolPanel();break;case'configuration':configuration();break;case'close-panel':if(data){render();schedule();}else list();break;case'start':if(previewReady)action('create',{edition_id:newParent,protocol_id:newParent?null:newSpec.study_id,basis:q('[data-st=basis]').value,tier:q('[data-st=tier]').value});break;case'reproduce':action('reproduce');break;case'resume':action('resume');break;case'fresh':action('fresh');break;case'cancel':action('cancel');break;case'export':action('export');break;case'history':showPanel('history',`<h1>Edition history</h1><p class="st-edition-id">Edition ${esc(edition)}</p><p>${esc(data.manifest.action)} · ${esc(data.manifest.created_at)}</p>${data.manifest.parent_edition_id?`<button data-edition="${esc(data.manifest.parent_edition_id)}">Open parent edition</button>`:'<p>This is an original application of the protocol.</p>'}<h2>Preserved report revisions</h2>${table(['Report','Published','Status'],data.publications.map(p=>[`<button data-publication="${esc(p.report_id)}">${esc(p.report_id.slice(0,12))}</button>`,esc(p.published_at),esc(p.status||'Recorded')]))}<p>Report revisions and complete case attempts are included in the reproduction bundle.</p>`);break;}});
 w.addEventListener('input',e=>{e.stopPropagation();if(e.target.dataset.u==='search'){uOptions();return;}if(e.target.dataset.u&&['autonomy','adaptation','design','worlds','seed','seeds','rationale'].includes(e.target.dataset.u))uInvalidate();if(e.target.dataset.st==='search')renderIndex();});w.addEventListener('change',e=>{e.stopPropagation();if(e.target.dataset.u==='parameter')uParameter();if(e.target.dataset.u==='trajectory')uEnvelope(e.target.value);if(e.target.dataset.u==='import'){const key=String(++generation);const file=e.target.files?.[0];if(file&&file.size<1000000)file.text().then(t=>{if(!opened||String(generation)!==key||panel!=='uncertainty')return;try{const draft=JSON.parse(t);if(draft.schema_version!=='dispatch-lab/uncertainty/1'||!Array.isArray(draft.blocks))throw Error('Unsupported uncertainty specification');uDraft=draft;uPreview=null;uEditor();status('Imported assumptions; preview validates every input before execution.');}catch(e){status(e.message);}});else status('Select a JSON specification under 1 MB');}if(e.target.dataset.st==='protocol-choice'){newSpec=protocolCatalogue.find(p=>p.study_id===e.target.value);tierOptions();preview();}else if(['basis','tier'].includes(e.target.dataset.st))preview();});
 w.addEventListener('keydown',e=>{e.stopPropagation();if(e.target.matches('circle[data-case]')&&['Enter',' '].includes(e.key)){e.preventDefault();casePanel(e.target.dataset.case);}if(e.key==='Escape'){e.preventDefault();if(!q('.st-index').hidden){q('.st-index').hidden=true;q('[data-st=index]').focus();}else if(panel){generation++;if(data){render();schedule();}else list();}else close();}});
 return {open,close,isOpen:()=>opened};
}
if(typeof module!=='undefined')module.exports={studyEscape,studyAccept};
